message.content:
- Failures recur after finding a target: the agent puts it down too early, leaves placed items, or loops examining/opening containers instead of using the next required transform.
- Maintain reusable stages: find_target, take_target, transform, go_destination, put_target, plus wrong_inventory and pick_two placed_count/locations.
- on_init gives task-order skill; on_post_step updates stage; make_pre_hint gives deduped soft guidance; on_before_action blocks only premature/wrong puts, skipped transforms, or taking back placed items.
- Avoided numbered force actions and broad forcing, so successful trajectories are preserved while nudging the general ALFWorld subgoal order.
</think>
<patch>{
  "benchmark": "alfworld",
  "description": "Maintain target transform and placement stage guidance to prevent premature puts and transform skips.",
  "actions": [
    {
      "type": "add_code_hook",
      "hook": "on_init",
      "code": "def hook(ctx, nb):
    nb['stage'] = 'find_target'
    nb['placed_count'] = 0
    nb['last_hint'] = ''
    nb['placed_locations'] = []
    nb['transformed'] = False
    skill = 'Use ALFWorld order: find and take the target, do any required clean heat cool or slice transform while carrying it, then put it at the destination. For two-object tasks, leave placed targets and reuse the same destination.'
    return {'skills': [{'text': skill}], 'tool_hint': 'Do not put the target down before the required transform; do not take back items already placed.'}"
    },
    {
      "type": "add_code_hook",
      "hook": "on_post_step",
      "code": "def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for p in path.split('.'):
        if isinstance(cur, dict) and p in cur:
            cur = cur.get(p)
        else:
            return default
    return cur

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def carry(target, inv, world):
    if not target:
        return False
    text = ' ' + str(inv).lower() + ' '
    return target in text or ('you are carrying' + target + ' in your') in text or world.get('inventory', '')

def hook(ctx, nb):
    tt = str(getv(ctx, 'task.task_type', '') or '').lower()
    target = str(getv(ctx, 'task.target_type', '') or '').lower()
    dest = str(getv(ctx, 'task.destination_type', '') or '').lower()
    if not target:
        return None
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    else:
        act = str(getv(ctx, 'action.final_action', '') or getv(ctx, 'action.normalized', '') or getv(ctx, 'action.raw', '') or '').lower()
        obs = str(ctx.get('observation', '') or '').lower()
        if act.startswith(verb + ' ' + target + ' ') or (' ' + verb + ' ' + target + ' ') in obs:
            nb['transformed'] = True
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    world = getv(ctx, 'world', {})
    if isinstance(world, dict):
        pc = max(pc, int(world.get('placed_count', 0) or 0))
    inv = getv(ctx, 'world.inventory', '')
    holding = carry(target, inv, world)
    admissible = ctx.get('admissible', []) or []
    has_take = False
    has_put = False
    has_trans = False
    for a in admissible:
        al = str(a).lower()
        if al.startswith('take ' + target + ' '):
            has_take = True
        if al.startswith('put ' + target + ' ') and (not dest or dest in al):
            has_put = True
        if verb and al.startswith(verb + ' ' + target + ' '):
            has_trans = True
    take_ready = has_take and not (verb and not nb.get('transformed'))
    locs = nb.get('placed_locations') or []
    if not isinstance(locs, list):
        locs = []
    if isinstance(world, dict) and isinstance(world.get('placed_locations'), list):
        locs = list(locs) + list(world.get('placed_locations'))
    elif isinstance(world, dict) and world.get('placed_locations'):
        locs.append(str(world.get('placed_locations')).lower())
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    if pc > 0 and pc < 2 and act.startswith('put ' + target + ' ') and dest and dest in act and dest not in locs:
        locs.append(act.split(' in/on ', 1)[1])
        nb['placed_locations'] = locs
    if pc >= 2 and verb and not nb.get('transformed') and take_ready and (act.startswith('go ') or act.startswith('examine ')):
        nb['stage'] = 'transform'
    elif holding and verb and not nb.get('transformed') and (take_ready or has_trans):
        nb['stage'] = 'transform'
    elif holding and dest and (has_put or getv(ctx, 'predicates.remaining_steps_low', False) or getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)):
        nb['stage'] = 'put_target'
    elif holding:
        nb['stage'] = 'go_destination'
    elif take_ready:
        nb['stage'] = 'take_target'
    else:
        nb['stage'] = 'find_target'
    if not holding and dest and getv(ctx, 'action.final_action', '') and getv(ctx, 'action.final_action', '').startswith('put ' + target + ' ') and dest in getv(ctx, 'action.final_action', '') and not verb and not nb.get('transformed'):
        nb['wrong_inventory'] = 'placed without transform'
    nb['transform_verb'] = verb
    nb['target_type'] = target
    nb['destination_type'] = dest
    return None"
    },
