      "type": "add_code_hook",
      "hook": "make_pre_hint",
      "code": "def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for p in path.split('.'):
        if isinstance(cur, dict) and p in cur:
            cur = cur.get(p)
        else:
            return default
    return cur

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def emit(nb, msg):
    if not msg or nb.get('last_hint') == msg:
        return None
    nb['last_hint'] = msg
    return {'message': msg}

def hook(ctx, nb):
    tt = str(getv(ctx, 'task.task_type', '') or nb.get('task_type', '') or '').lower()
    target = nb.get('target_type') or str(getv(ctx, 'task.target_type', '') or '').lower()
    dest = nb.get('destination_type') or str(getv(ctx, 'task.destination_type', '') or '').lower()
    verb = nb.get('transform_verb') or needverb(tt)
    if not target or not verb:
        return None
    stage = nb.get('stage')
    pc = nb.get('placed_count') or 0
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if stage == 'transform' and pc < 2:
        return emit(nb, 'Transform the carried ' + target + ' with the available ' + verb + ' action before putting it anywhere.')
    if stage == 'put_target' and dest:
        return emit(nb, 'Carry the transformed ' + target + ' to a ' + dest + ' and use the put action there.')
    if stage == 'take_target' and pc > 0 and pc < 2 and dest:
        return emit(nb, 'Do not take back a target already placed at the ' + dest + '; find another ' + target + ' and keep the same destination.')
    return None"
    },
    {
      "type": "add_code_hook",
      "hook": "on_before_action",
      "code": "def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for p in path.split('.'):
        if isinstance(cur, dict) and p in cur:
            cur = cur.get(p)
        else:
            return default
    return cur

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def hook(ctx, nb):
    tt = str(getv(ctx, 'task.task_type', '') or nb.get('task_type', '') or '').lower()
    target = nb.get('target_type') or str(getv(ctx, 'task.target_type', '') or '').lower()
    dest = nb.get('destination_type') or str(getv(ctx, 'task.destination_type', '') or '').lower()
    verb = nb.get('transform_verb') or needverb(tt)
    action = str(getv(ctx, 'action.final_action', '') or getv(ctx, 'action.normalized', '') or getv(ctx, 'action.raw', '') or '').lower()
    if not action or not target or not verb:
        return None
    holding = bool(getv(ctx, 'world.inventory', '')) or bool(nb.get('holding_target'))
    carrying_target = bool(target in str(getv(ctx, 'world.inventory', '')).lower()) or bool(nb.get('holding_target')) or (action.startswith('put ' + target + ' ') and 'pick up' in str(ctx.get('observation', '')).lower())
    transformed = bool(nb.get('transformed')) or bool(verb in action and target in action and 'pick up' in str(ctx.get('observation', '')).lower())
    pc = nb.get('placed_count') or 0
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if action.startswith('put ' + target + ' ') and dest and dest in action and not transformed and pc < 2:
        return {'kind': 'block_and_prompt', 'message': 'Do not put the target at the destination yet. First use the available transform action on the carried ' + target + '; then put it at the destination.'}
    if verb and pc > 0 and pc < 2 and not nb.get('transformed') and action.startswith('take ' + target + ' '):
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target already placed at the destination. Keep the placed item there and continue with the next required subgoal.'}
    if verb and action.startswith('examine ') and not transformed and (getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)) and (holding or carrying_target or getv(ctx, 'world.target_found', False)):
        return {'kind': 'block_and_prompt', 'message': 'This looks like a loop. Use the available transform action on the carried ' + target + ' instead of only examining containers.'}
    return None"
    }
